// src/lib/mcp/tools/get-program-analytics.ts
var get_program_analytics_default = defineTool4({
  name: "get_program_analytics",
  title: "Get program analytics",
  description: "Return 2016-2025 program analytics for a Power 4 team: SP+ ranks, 247Sports recruiting composite ranks, and the Delta (recruiting minus performance) metric with average and standard deviation.",
  inputSchema: {
    team: z4.string().min(1).describe("Team name (see list_teams).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ team }) => {
    const row = ANALYTICS_DATA.find(
      (t) => t.team.toLowerCase() === team.toLowerCase()
    );
    if (!row) {
      return {
        content: [
          {
            type: "text",
            text: `No analytics found for "${team}". Call list_teams for valid names.`
          }
        ],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(row, null, 2) }],
      structuredContent: row
    };
  }
});

// src/lib/mcp/index.ts
var mcp_default = defineMcp({
  name: "p4-oddsmaker-mcp",
  title: "P4 Oddsmaker (2026)",
  version: "0.1.0",
  instructions: "Public read-only tools for the 2026 Power 4 college football season projection app. Use list_teams to discover team names, get_schedule for a team's 2026 schedule, project_season_wins to compute the win distribution given per-game win percentages, and get_program_analytics for 2016-2025 SP+/247Sports/Delta metrics. All data is public and this server is not affiliated with the University of Nebraska.",
  tools: [list_teams_default, get_schedule_default, project_season_wins_default, get_program_analytics_default]
});

